SELECT p.id,p.name,COALESCE(SUM(x.w),0) wins,COALESCE(SUM(x.l),0) losses FROM players p LEFT JOIN (SELECT winner player,COUNT(*) w,0 l FROM matches WHERE loser_rank BETWEEN 1 AND 10 AND status IN ('Completed','Aborted') GROUP BY winner UNION ALL SELECT loser player,0 w,COUNT(*) l FROM matches WHERE winner_rank BETWEEN 1 AND 10 AND status IN ('Completed','Aborted') GROUP BY loser) x ON x.player=p.id WHERE p.highest_rank=1 GROUP BY p.id,p.name ORDER BY wins DESC,p.name